// Emits every sim sample since the previous tick with its own ms timestamp.
let st = context.get('state'); if (!st) { st = {}; context.set('state', st); }
const lines = global.get('sim').tick(st, Date.now());
if (!lines) return null;
msg.payload = lines;
msg.url = env.get('INFLUX_URL') + '/api/v2/write?org=' + encodeURIComponent(env.get('INFLUX_ORG')) +
          '&bucket=' + encodeURIComponent(env.get('INFLUX_BUCKET')) + '&precision=ms';
msg.headers = { 'Authorization': 'Token ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'text/plain; charset=utf-8' };
msg.method = 'POST';
node.status({ fill: 'green', shape: 'dot', text: lines.split('\n').length + ' points' });
return msg;
